head.script:
scwin.init = function() {
    console.log("main.xml done")
    localStorage.setItem("log", "main.xml done");
}
scwin.iframe1_oniframeload = function() {
    console.log("iframe1_oniframeload");
    localStorage.setItem("log2", "iframe1_oniframeload")
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 개발자모드(F12)에서 샘플파일을 실행 후 console창을 확인한다.
    //1. Execute the sample file in Developer mode (F12) and check the console window.
    //Verify 1. The sequence shown in the console window is shown below. console.log output order, main.xml done, iframe1.xml done, iframe1_oniframeload, iframe11 done, iframe11_oniframeload, (See previous attachment for console order)
    WebSquare.wUnit.addCommand("pause", "2000");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') == 'main.xml done'", "true");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log1') == 'iframe1.xml done'", "true");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log2') == 'iframe1_oniframeload'", "true");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log3') == 'iframe11 done'", "true");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log4') == 'iframe11_oniframeload'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log')");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log1')");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log2')");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log3')");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log4')");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
	scwin.init()
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 13-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
